// From bars to sessions (SPEC § 5, § 7) and the per-session evaluation of setups and outcomes
// (SPEC § 8, LANGUAGE.md §§ 5 to 10).

import { type Calendar, type EventKind, hasRth, priorSession, rthClose } from './calendar';
import type { Bars } from './data';
import type { EventOutcome, EventSpec, Expr, Field, Win } from './lang/ast';
import type { ParsedQueryInternal } from './lang/query';
import { MS_MINUTE, isoWeekday, wallClock } from './time';

export type Reason =
  | 'outside_data'
  | 'no_bars'
  | 'no_open_bar'
  | 'no_regular_hours'
  | 'closed_early'
  | 'no_prior_session'
  | 'event_not_covered'
  | 'divide_by_zero'
  | 'tie_excluded';

export const REASONS: readonly Reason[] = [
  'outside_data',
  'no_bars',
  'no_open_bar',
  'no_regular_hours',
  'closed_early',
  'no_prior_session',
  'event_not_covered',
  'divide_by_zero',
  'tie_excluded',
];

/** An undefined value, with its reason. One shared instance per reason. */
export class Undef {
  constructor(readonly reason: Reason) {}
}
const U: Record<Reason, Undef> = Object.fromEntries(REASONS.map((r) => [r, new Undef(r)])) as Record<Reason, Undef>;

// ---- assignment -------------------------------------------------------------

export interface Ignored {
  offCalendar: number;
  halt: number;
  afterClose: number;
  outOfCoverage: number;
}

export interface Sessions {
  cal: Calendar;
  bars: Bars;
  /** assigned bars in order: their index in `bars` and their session minute */
  aIdx: Int32Array;
  aMin: Int32Array;
  /** per trading-day index: [first, end) positions into aIdx, or -1 */
  dayFirst: Int32Array;
  dayEnd: Int32Array;
  assigned: number;
  ignored: Ignored;
  /** data span [S, E) */
  S: number;
  E: number;
  firstAssigned: number;
  lastAssigned: number;
}

/** Assign every bar to a session (SPEC § 5.1). */
export function assignSessions(bars: Bars, cal: Calendar): Sessions {
  const n = bars.length;
  const aIdx = new Int32Array(n);
  const aMin = new Int32Array(n);
  const nd = cal.days.length;
  const dayFirst = new Int32Array(nd).fill(-1);
  const dayEnd = new Int32Array(nd).fill(-1);
  const ignored: Ignored = { offCalendar: 0, halt: 0, afterClose: 0, outOfCoverage: 0 };
  let k = 0;
  for (let i = 0; i < n; i++) {
    const t = bars.t[i];
    const wc = wallClock(cal.ny, t);
    if (!wc) {
      ignored.outOfCoverage++;
      continue;
    }
    const [L, c] = wc;
    if (c >= 1020 && c < 1080) {
      ignored.halt++;
      continue;
    }
    const D = c >= 1080 ? L + 1 : L;
    if (D < cal.coverageStart || D > cal.coverageEnd) {
      ignored.outOfCoverage++;
      continue;
    }
    const idx = cal.indexOfDay.get(D);
    if (idx === undefined) {
      ignored.offCalendar++;
      continue;
    }
    const m = (c - 1080 + 1440) % 1440;
    if (m >= cal.close[idx]) {
      ignored.afterClose++;
      continue;
    }
    aIdx[k] = i;
    aMin[k] = m;
    if (dayFirst[idx] < 0) dayFirst[idx] = k;
    dayEnd[idx] = k + 1;
    k++;
  }
  const S = k > 0 ? bars.t[aIdx[0]] : 0;
  const E = k > 0 ? bars.t[aIdx[k - 1]] + MS_MINUTE : 0;
  return {
    cal,
    bars,
    aIdx: aIdx.subarray(0, k),
    aMin: aMin.subarray(0, k),
    dayFirst,
    dayEnd,
    assigned: k,
    ignored,
    S,
    E,
    firstAssigned: k > 0 ? bars.t[aIdx[0]] : 0,
    lastAssigned: k > 0 ? bars.t[aIdx[k - 1]] : 0,
  };
}

/** Trading-day indices of the analysis range (SPEC § 7.3). */
export function analysisRange(s: Sessions, from: number | null, to: number | null): number[] {
  const out: number[] = [];
  const { cal } = s;
  if (s.assigned === 0) return out;
  for (let i = 0; i < cal.days.length; i++) {
    const d = cal.days[i];
    if (from !== null && d < from) continue;
    if (to !== null && d > to) break;
    const open = cal.base[i];
    const close = open + cal.close[i] * MS_MINUTE;
    if (open < s.E && close > s.S) out.push(i);
  }
  return out;
}

/** First position in [lo, hi) of day positions whose minute is >= m. */
function lowerBound(aMin: Int32Array, lo: number, hi: number, m: number): number {
  while (lo < hi) {
    const mid = (lo + hi) >>> 1;
    if (aMin[mid] < m) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/** Positions [lo, hi) of a day's bars with session minute in [a, b). */
export function dayRange(s: Sessions, day: number, a: number, b: number): [number, number] {
  const f = s.dayFirst[day];
  if (f < 0) return [0, 0];
  const e = s.dayEnd[day];
  return [lowerBound(s.aMin, f, e, a), lowerBound(s.aMin, f, e, b)];
}

/** Number of a day's bars inside its regular hours. */
export function rthBarCount(s: Sessions, day: number): number {
  const [lo, hi] = dayRange(s, day, 930, rthClose(s.cal, day));
  return hi - lo;
}

// ---- the evaluator ------------------------------------------------------------

interface Agg {
  lo: number;
  hi: number;
  /** open of the bar at the window's first minute, or NaN */
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

export interface OutcomeResult {
  /** 'hit' | 'miss', or the reason it is undefined */
  value: 'hit' | 'miss' | Undef;
  minutes: number | null;
  tie: boolean;
  clipped: boolean;
  /** observation window length after clipping (event outcomes) */
  windowLength: number;
}

export class Evaluator {
  private cache = new Map<number, Agg | Undef>();
  private readonly cal: Calendar;
  constructor(
    private readonly s: Sessions,
    private readonly q: ParsedQueryInternal,
    private readonly tie: 'miss' | 'hit' | 'exclude',
  ) {
    this.cal = s.cal;
  }

  /** The aggregate of day's bars in [a, b) (b already clipped), or why it has none. */
  private agg(day: number, a: number, b2: number): Agg | Undef {
    const key = (day * 1441 + a) * 1441 + b2;
    const c = this.cache.get(key);
    if (c) return c;
    const [lo, hi] = dayRange(this.s, day, a, b2);
    let r: Agg | Undef;
    if (lo >= hi) r = U.no_bars;
    else {
      const b = this.s.bars;
      let high = -Infinity;
      let low = Infinity;
      let volume = 0;
      for (let p = lo; p < hi; p++) {
        const i = this.s.aIdx[p];
        if (b.high[i] > high) high = b.high[i];
        if (b.low[i] < low) low = b.low[i];
        if (b.volume) volume += b.volume[i];
      }
      const first = this.s.aIdx[lo];
      r = {
        lo,
        hi,
        open: this.s.aMin[lo] === a ? b.open[first] : NaN,
        high,
        low,
        close: b.close[this.s.aIdx[hi - 1]],
        volume,
      };
    }
    this.cache.set(key, r);
    return r;
  }

  /** A window selector on a day, with the availability rules of LANGUAGE.md § 5.3. */
  windowValue(day: number, a: number, b: number, field: Field): number | Undef {
    const cal = this.cal;
    if (a >= 930 && !hasRth(cal, day)) return U.no_regular_hours;
    const close = cal.close[day];
    const b2 = b < close ? b : close;
    if (b2 <= a) return U.closed_early;
    const base = cal.base[day];
    const first = base + a * MS_MINUTE;
    if (field === 'open') {
      if (first < this.s.S || first + MS_MINUTE > this.s.E) return U.outside_data;
    } else if (first < this.s.S || base + b2 * MS_MINUTE > this.s.E) return U.outside_data;
    const g = this.agg(day, a, b2);
    if (g instanceof Undef) return g;
    switch (field) {
      case 'open':
        return Number.isNaN(g.open) ? U.no_open_bar : g.open;
      case 'body':
        return Number.isNaN(g.open) ? U.no_open_bar : g.close - g.open;
      case 'high':
        return g.high;
      case 'low':
        return g.low;
      case 'close':
        return g.close;
      case 'range':
        return g.high - g.low;
      case 'mid':
        return (g.high + g.low) / 2;
      case 'volume':
        return g.volume;
    }
  }

  private winOn(D: number, w: Win, field: Field): number | Undef {
    switch (w.k) {
      case 'rth':
        return this.windowValue(D, 930, 1320, field);
      case 'overnight':
        return this.windowValue(D, 0, 930, field);
      case 'session':
        return this.windowValue(D, 0, 1380, field);
      case 'or':
        return this.windowValue(D, 930, 930 + w.n, field);
      case 'window':
        return this.windowValue(D, w.a, w.b, field);
      case 'bar':
        return this.windowValue(D, w.t, w.t + w.len, field);
      case 'prior': {
        const P = priorSession(this.cal, D, w.n);
        if (P < 0) return U.no_prior_session;
        return w.session ? this.windowValue(P, 0, 1380, field) : this.windowValue(P, 930, 1320, field);
      }
    }
  }

  private prior(D: number, k: number, field: Field): number | Undef {
    const P = priorSession(this.cal, D, k);
    if (P < 0) return U.no_prior_session;
    return this.windowValue(P, 930, 1320, field);
  }

  private covered(kind: EventKind, lo: number, hi: number): boolean {
    const n = this.cal.days.length;
    if (lo < 0 || hi >= n) return false;
    const [cs, ce] = this.cal.eventCoverage[kind];
    return this.cal.days[lo] >= cs && this.cal.days[hi] <= ce;
  }

  private eventFlag(D: number, kinds: EventKind[], before: number, after: number): boolean | Undef {
    const lo = D - after;
    const hi = D + before;
    for (const k of kinds) if (!this.covered(k, lo, hi)) return U.event_not_covered;
    for (const k of kinds) {
      const days = this.cal.eventDays[k];
      // any event day in [lo, hi]
      let a = 0, b = days.length;
      while (a < b) {
        const m = (a + b) >>> 1;
        if (days[m] < lo) a = m + 1;
        else b = m;
      }
      if (a < days.length && days[a] <= hi) return true;
    }
    return false;
  }

  private daysSince(D: number, k: EventKind): number | Undef {
    if (!this.covered(k, D, D)) return U.event_not_covered;
    const days = this.cal.eventDays[k];
    let a = 0, b = days.length;
    while (a < b) {
      const m = (a + b) >>> 1;
      if (days[m] <= D) a = m + 1;
      else b = m;
    }
    if (a === 0) return U.event_not_covered;
    const E = days[a - 1];
    if (!this.covered(k, E, D)) return U.event_not_covered;
    return D - E;
  }

  private daysTo(D: number, k: EventKind): number | Undef {
    if (!this.covered(k, D, D)) return U.event_not_covered;
    const days = this.cal.eventDays[k];
    let a = 0, b = days.length;
    while (a < b) {
      const m = (a + b) >>> 1;
      if (days[m] < D) a = m + 1;
      else b = m;
    }
    if (a >= days.length) return U.event_not_covered;
    const E = days[a];
    if (!this.covered(k, D, E)) return U.event_not_covered;
    return E - D;
  }

  /** A numeric value (prices, distances, counts, weekdays as 1..5). */
  num(e: Expr, D: number): number | Undef {
    switch (e.t) {
      case 'num': {
        if (e.unit === 'none') return e.value;
        if (e.unit === 'pts') return e.value;
        if (e.unit === 'ticks') return e.value * (this.q.tickSize ?? NaN);
        const ref = e.of ? this.num(e.of, D) : this.prior(D, 1, 'close');
        if (ref instanceof Undef) return ref;
        return (e.value / 100) * ref;
      }
      case 'win':
        return this.winOn(D, e.win, e.field);
      case 'gap': {
        const o = this.windowValue(D, 930, 1320, 'open');
        const pc = this.prior(D, 1, 'close');
        if (o instanceof Undef) return o;
        if (pc instanceof Undef) return pc;
        return o - pc;
      }
      case 'adr': {
        let sum = 0;
        for (let i = 1; i <= e.n; i++) {
          const r = this.prior(D, i, 'range');
          if (r instanceof Undef) return r;
          sum += r;
        }
        return sum / e.n;
      }
      case 'atr': {
        let sum = 0;
        for (let i = 1; i <= e.n; i++) {
          const h = this.prior(D, i, 'high');
          if (h instanceof Undef) return h;
          const pc = this.prior(D, i + 1, 'close');
          if (pc instanceof Undef) return pc;
          const l = this.prior(D, i, 'low');
          if (l instanceof Undef) return l;
          sum += Math.max(h, pc) - Math.min(l, pc);
        }
        return sum / e.n;
      }
      case 'weekday':
        return isoWeekday(this.cal.days[D]);
      case 'wdname':
        return e.day;
      case 'days_since':
        return this.daysSince(D, e.kind);
      case 'days_to':
        return this.daysTo(D, e.kind);
      case 'at':
        return this.windowValue(D, 0, e.time, 'close');
      case 'neg': {
        const x = this.num(e.x, D);
        return x instanceof Undef ? x : -x;
      }
      case 'bin': {
        const l = this.num(e.l, D);
        const r = this.num(e.r, D);
        if (l instanceof Undef) return l;
        if (r instanceof Undef) return r;
        switch (e.op) {
          case '+':
            return l + r;
          case '-':
            return l - r;
          case '*':
            return l * r;
          case '/':
            return r === 0 ? U.divide_by_zero : l / r;
        }
      }
      // falls through only for a malformed tree
      case 'fn': {
        if (e.t !== 'fn') break;
        const vals: number[] = [];
        let bad: Undef | null = null;
        for (const a of e.args) {
          const v = this.num(a, D);
          if (v instanceof Undef) {
            if (!bad) bad = v;
          } else vals.push(v);
        }
        if (bad) return bad;
        if (e.fn === 'abs') return Math.abs(vals[0]);
        if (e.fn === 'mid') return (vals[0] + vals[1]) / 2;
        let acc = vals[0];
        for (let i = 1; i < vals.length; i++) acc = e.fn === 'min' ? Math.min(acc, vals[i]) : Math.max(acc, vals[i]);
        return acc;
      }
    }
    throw new Error(`not a numeric expression: ${e.t}`);
  }

  /** A condition. Undefined is strict: any undefined value makes the whole condition undefined. */
  bool(e: Expr, D: number): boolean | Undef {
    switch (e.t) {
      case 'all':
        return true;
      case 'early_close':
        return this.cal.earlyClose[D] === 1;
      case 'event':
        return this.eventFlag(D, e.kinds, e.before, e.after);
      case 'cmp': {
        const l = this.num(e.l, D);
        const r = this.num(e.r, D);
        if (l instanceof Undef) return l;
        if (r instanceof Undef) return r;
        switch (e.op) {
          case '>':
            return l > r;
          case '>=':
            return l >= r;
          case '<':
            return l < r;
          case '<=':
            return l <= r;
          case '=':
            return l === r;
          case '!=':
            return l !== r;
        }
      }
      // eslint-disable-next-line no-fallthrough
      case 'between': {
        if (e.t !== 'between') break;
        const x = this.num(e.x, D);
        const a = this.num(e.a, D);
        const b = this.num(e.b, D);
        if (x instanceof Undef) return x;
        if (a instanceof Undef) return a;
        if (b instanceof Undef) return b;
        return x >= a && x <= b;
      }
      case 'in': {
        const x = this.num(e.x, D);
        if (x instanceof Undef) return x;
        let hit = false;
        for (const it of e.list) {
          const v = this.num(it, D);
          if (v instanceof Undef) return v;
          if (v === x) hit = true;
        }
        return e.neg ? !hit : hit;
      }
      case 'and':
      case 'or': {
        const l = this.bool(e.l, D);
        const r = this.bool(e.r, D);
        if (l instanceof Undef) return l;
        if (r instanceof Undef) return r;
        return e.t === 'and' ? l && r : l || r;
      }
      case 'not': {
        const x = this.bool(e.x, D);
        return x instanceof Undef ? x : !x;
      }
    }
    throw new Error(`not a condition: ${e.t}`);
  }

  setup(D: number): boolean | Undef {
    return this.bool(this.q.setup, D);
  }

  outcome(D: number): OutcomeResult {
    const o = this.q.outcome;
    if (o.form === 'state') {
      const v = this.bool(o.expr, D);
      return { value: v instanceof Undef ? v : v ? 'hit' : 'miss', minutes: null, tie: false, clipped: false, windowLength: 0 };
    }
    return this.eventOutcome(o, D);
  }

  private eventOutcome(o: EventOutcome, D: number): OutcomeResult {
    const und = (r: Undef, clipped = false): OutcomeResult => ({ value: r, minutes: null, tie: false, clipped, windowLength: 0 });
    const L1 = this.num(o.first.level, D);
    const L2 = o.second ? this.num(o.second.level, D) : 0;
    if (L1 instanceof Undef) return und(L1);
    if (L2 instanceof Undef) return und(L2);
    const w = this.q.window;
    const cal = this.cal;
    const usesRthClose = w.endKind === 'close' || w.endKind === 'default';
    const cap = usesRthClose ? rthClose(cal, D) : cal.close[D];
    const start = w.start;
    const end = w.end < cap ? w.end : cap;
    if (end <= start) return und(!hasRth(cal, D) && start >= 930 ? U.no_regular_hours : U.closed_early);
    // An end naming the day's own close (by close, by session_close, the default) is that day's
    // close and is never shortened; only a clock end or a within end past an early close is.
    const fixedEnd = w.endKind === 'time' || w.endKind === 'within';
    const clipped = fixedEnd && end < Math.min(w.end, 1380);
    const base = cal.base[D];
    if (base + start * MS_MINUTE < this.s.S || base + end * MS_MINUTE > this.s.E) return und(U.outside_data, clipped);
    const [lo, hi] = dayRange(this.s, D, start, end);
    if (lo >= hi) return und(U.no_bars, clipped);
    const windowLength = end - start;
    const tA = this.firstEvent(o.first, L1, lo, hi, start, end, -Infinity);
    const res = (value: 'hit' | 'miss', t: number | null, tie = false): OutcomeResult => ({
      value,
      minutes: t === null ? null : t - start,
      tie,
      clipped,
      windowLength,
    });
    if (o.neg) return res(tA === Infinity ? 'hit' : 'miss', null);
    if (!o.seq) return tA === Infinity ? res('miss', null) : res('hit', tA);
    if (tA === Infinity) return res('miss', null);
    if (o.seq === 'then') {
      const tB = this.firstEvent(o.second!, L2 as number, lo, hi, start, end, tA);
      return tB === Infinity ? res('miss', null) : res('hit', tB);
    }
    const tB = this.firstEvent(o.second!, L2 as number, lo, hi, start, end, -Infinity);
    if (tA < tB) return res('hit', tA);
    if (tA === tB) {
      if (this.tie === 'hit') return res('hit', tA, true);
      if (this.tie === 'miss') return res('miss', null, true);
      return { value: U.tie_excluded, minutes: null, tie: true, clipped, windowLength };
    }
    return res('miss', null);
  }

  /** The first event time (session minute, end of the bar) strictly after `after`, or Infinity. */
  private firstEvent(ev: EventSpec, L: number, lo: number, hi: number, start: number, end: number, after: number): number {
    const b = this.s.bars;
    const { aIdx, aMin } = this.s;
    if (ev.barSize === 1 || (ev.kind !== 'closes_above' && ev.kind !== 'closes_below')) {
      for (let p = lo; p < hi; p++) {
        const m = aMin[p];
        if (m + 1 <= after) continue;
        const i = aIdx[p];
        let ok: boolean;
        switch (ev.kind) {
          case 'touches':
            ok = b.low[i] <= L && L <= b.high[i];
            break;
          case 'trades_above':
            ok = b.high[i] > L;
            break;
          case 'trades_below':
            ok = b.low[i] < L;
            break;
          case 'closes_above':
            ok = b.close[i] > L;
            break;
          case 'closes_below':
            ok = b.close[i] < L;
            break;
        }
        if (ok) return m + 1;
      }
      return Infinity;
    }
    const N = ev.barSize;
    let g = start + ((((930 - start) % N) + N) % N);
    let p = lo;
    for (; g + N <= end; g += N) {
      while (p < hi && aMin[p] < g) p++;
      let last = -1;
      while (p < hi && aMin[p] < g + N) {
        last = p;
        p++;
      }
      if (last < 0 || g + N <= after) continue;
      const c = b.close[aIdx[last]];
      if (ev.kind === 'closes_above' ? c > L : c < L) return g + N;
    }
    return Infinity;
  }
}
